contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run performs a Put with provided lockTime and amount; asserts that when Put doesn't revert,
    // the observable balances (address(c).balance and c.Acc(address(this)).balance) increase by amount.
    function run(uint lockTime, uint amount) public payable {
        require(address(this).balance >= amount);

        // read before-values
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));

        // perform the call under test: send 'amount' wei to c.Put(lockTime)
        bool reverted;
        try c.Put{value: amount}(lockTime) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read after-values
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this));

        // If the call did not revert then both the contract-wide balance and the holder balance
        // for this tester must have increased by exactly `amount` (no more, no less).
        assert(reverted || (afterContractBalance == beforeContractBalance + amount && afterHolderBalance == beforeHolderBalance + amount));
    }

    // allow receiving refunds if Collect sends Ether back to this test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We attempt to exercise Collect: parameters are amount to collect and an initial deposit to ensure balance.
    // We make an initial Put to ensure the caller has some balance, then call Collect and observe effects.
    function run(uint initialDeposit, uint lockTime, uint collectAmount) public payable {
        // ensure this test contract can pay the initial deposit to c
        require(address(this).balance >= initialDeposit);

        // read before-values
        uint beforeContractBalance = address(c).balance;
        (uint beforeUnlock, uint beforeHolderBalance) = c.Acc(address(this));

        // perform an initial Put to add funds to our holder in c (may revert if Put reverts)
        bool putReverted;
        try c.Put{value: initialDeposit}(lockTime) {
            putReverted = false;
        } catch {
            putReverted = true;
        }

        // read intermediate values
        uint midContractBalance = address(c).balance;
        (uint midUnlock, uint midHolderBalance) = c.Acc(address(this));

        // Now try to Collect collectAmount
        bool collectReverted;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // read after-values
        uint afterContractBalance = address(c).balance;
        (uint afterUnlock, uint afterHolderBalance) = c.Acc(address(this));

        // General rule:
        // If Collect did not revert, then contract balance strictly decreased by exactly collectAmount
        // AND the holder's stored balance did not increase (afterHolderBalance <= midHolderBalance)
        // (we allow holder balance decrease to be >= collectAmount due to any internal behavior,
        // but the contract's ETH must go down exactly by collectAmount on success).
        // If Collect reverted, no requirement (covered by the disjunction).
        assert(collectReverted || (afterContractBalance + collectAmount == midContractBalance && afterHolderBalance <= midHolderBalance));
    }

    // allow receiving refunds if Collect sends Ether back to this test
    receive() external payable {}
}

