contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run attempts to call Put to fund msg.sender (this contract) and then tries Collect.
    // params:
    //  fundAmount: amount of wei to send to Put (or fallback) to increase this holder's balance
    //  lockTime: lock time argument for Put
    //  collectAmount: amount to request in Collect
    function run(uint fundAmount, uint lockTime, uint collectAmount) public payable {
        require(address(this).balance >= fundAmount);
        // Record balances before any interaction
        uint holderBalanceBefore = c.Acc(address(this)).balance;
        uint contractBalanceBefore = address(c).balance;

        // Fund the holder by calling Put with value fundAmount
        c.Put{value: fundAmount}(lockTime);

        // After funding, balances should have increased appropriately
        uint holderBalanceAfterFund = c.Acc(address(this)).balance;
        uint contractBalanceAfterFund = address(c).balance;

        // Now attempt to Collect collectAmount. Capture whether it reverted.
        bool reverted;
        // We must call Collect as a top-level statement; use try/catch via low-level call to detect revert
        // Use address(c).call to invoke Collect — this still interacts through public surface
        bytes memory payload = abi.encodeWithSignature("Collect(uint256)", collectAmount);
        (bool ok, ) = address(c).call{value: 0}(payload);
        reverted = !ok;

        // Read balances after attempted collect
        uint holderBalanceAfter = c.Acc(address(this)).balance;
        uint contractBalanceAfter = address(c).balance;

